type Node = {
    key: number;
    left: Node | null;
    right: Node | null;
};

function insert(root: Node | null, key: number): Node {
    if (root === null) {
        return { key, left: null, right: null };
    }
    if (key < root.key) {
        root.left = insert(root.left, key);
    } else {
        root.right = insert(root.right, key);
    }
    return root;
}

const deadlines = [5, 10, 15, 20, 25, 30];
let root: Node | null = null;
for (const deadline of deadlines) {
    root = insert(root, deadline);
}
